depth_cols = {30: 2, 48: 3, 72: 4, 120: 5, 180: 6}
depth_corr = {}
for r in range(6, ws_d.max_row+1):
    sz = str(ws_d.cell(r, 1).value).strip()
    depth_corr[sz] = {}
    for d, c in depth_cols.items():
        depth_corr[sz][d] = float(ws_d.cell(r, c).value)

